import { useEffect, useRef } from 'react';
import { getMeta } from '@/db/schema.js';
import { activityKnown, activityOn, holdSurface, signal } from '@/lib/surface.js';

/** The server's `meta.trigger` values (spec, API "Fixed values"): what made the paywall show. */
export type PaywallTrigger =
  | 'ai_daily'
  | 'ai_monthly'
  | 'ai_unconfirmed'
  | 'lex_daily'
  | 'read_daily'
  | 'sentence_daily'
  | 'notebooks'
  | 'pro_feature'
  | 'trial_ended'
  | 'offer'
  | 'user';

/**
 * The trigger for an offer of Pro, from the occasion that opened it
 * (`ProOffer`'s occasions, a moment, the full-screen offers). `ai_limit` is
 * the AI cards used up, told apart as the day's or the month's when the
 * paywall opens (meta `aiPauseKind`).
 */
export function triggerFor(occasion: string, moment = false): PaywallTrigger | 'ai_limit' {
  if (moment) return 'offer';
  switch (occasion) {
    case 'resting':
      return 'ai_limit';
    case 'notebook':
    case 'new_notebook':
      return 'notebooks';
    case 'settings':
    case 'plan_page':
      return 'user';
    case 'aiIdle':
    case 'readText':
    case 'voice':
    case 'lex':
    case 'sayIt':
    case 'sentence':
      return 'pro_feature';
    default:
      return 'pro_feature';
  }
}

async function resolve(trigger: PaywallTrigger | 'ai_limit'): Promise<PaywallTrigger> {
  if (trigger !== 'ai_limit') return trigger;
  const kind = await getMeta('aiPauseKind').catch(() => null);
  return kind === 'month' ? 'ai_monthly' : 'ai_daily';
}

/**
 * A paywall on screen (§9): `paywall.view` as it opens, with where it was
 * opened (`place`, the product signals' places) and what made it show
 * (`trigger`, the server's values); `paywall.dismiss` when it goes without a
 * purchase having started. While it is open the calls it makes (checkout,
 * the moment offer) say `app.paywall`.
 */
export function usePaywallActivity(
  place: string,
  trigger: PaywallTrigger | 'ai_limit',
  buying: boolean,
): void {
  const bought = useRef(buying);
  useEffect(() => {
    if (buying) bought.current = true;
  }, [buying]);
  useEffect(() => {
    const release = holdSurface('app.paywall');
    // The server does not take events: nothing is read or noted.
    if (activityKnown() && !activityOn()) return release;
    const said = resolve(trigger);
    void said.then((t) => {
      signal({ name: 'paywall.view', surface: 'app.paywall', meta: { place, trigger: t } });
    });
    return () => {
      release();
      if (bought.current) return;
      void said.then((t) => {
        signal({ name: 'paywall.dismiss', surface: 'app.paywall', meta: { place, trigger: t } });
      });
    };
  }, [place, trigger]);
}
