/**
 * Compare, then commit (uiux offers spec §2.4; offer presentation spec §5):
 * the plans as radio cards, yearly first and chosen, the honest anchors
 * under them (`pickerAnchors`: twelve monthly payments against the year, a
 * price per day; owner's pricing rules 2026-10-23), then ONE button that
 * carries the amount billed today, the trust row (with the web's 14-day
 * money-back) and the legal sentence for the chosen plan right under it. Shared by the Plan page, the offer
 * sheet and the full-screen offer, so the three can never drift apart.
 */
import { useId } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { ABOUT_LINKS } from '@/features/settings/about.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { Seal } from './art/Seal.js';
import { OfferCountdown, type OfferCountdownProps } from './OfferCountdown.js';
import {
  badgeWords,
  buyLabel,
  disclosure,
  pickerAnchors,
  trustLine,
  type BadgeKind,
  type PlanChoice,
  type Store,
} from './planChoices.js';
import type { Offer } from './offer.js';
import type { KeepProModel } from './keepProModel.js';
import { Rich } from './Rich.js';
import { serverNow } from '@/lib/serverClock.js';
import { bonusDays, trialDaysBackAdded, trialDaysLeft } from './offer.js';
import { formatPrice, paidPrices, useBilling } from './state.js';
import { runningTrial } from './trial.js';
import { restoreWords, type AppStoreRestore } from './useAppStoreRestore.js';
import { isNight, nightStyle } from './night.js';
import styles from './KeepPro.module.css';

/** The one badge on a screen: gold for an offer or a season, green for "Best value". */
export function OfferBadge({
  kind,
  offer,
}: {
  kind: BadgeKind;
  offer?: Offer | undefined;
}): React.JSX.Element {
  // The night (Black Friday) badge is a small piece of the night card: ink,
  // a mint dot, no gold seal (uiux spec 2026-10-24 §3.2).
  const night = kind !== 'best_value' && isNight(offer?.creative);
  return (
    <span
      className={cx(styles.badge, kind === 'best_value' && styles.badgeBest, night && styles.badgeNight)}
      style={night ? nightStyle(offer?.creative) : undefined}
    >
      {kind !== 'best_value' && !night && <Seal size={12} />}
      {badgeWords(kind, offer)}
    </span>
  );
}

export function PlanPicker({
  model,
  legend,
  legendHidden = false,
  disabled = false,
  countdown,
}: {
  model: KeepProModel;
  legend: string;
  legendHidden?: boolean;
  disabled?: boolean;
  /** The offer card's countdown (only the offer has one; one per screen). */
  countdown?: Omit<OfferCountdownProps, 'closesAt'> | undefined;
}): React.JSX.Element {
  const name = useId();
  const state = useBilling((s) => s.state);
  const anchors = pickerAnchors(model.choices, state);
  return (
    <>
      <fieldset className={styles.picker} disabled={disabled}>
        <legend className={legendHidden ? 'sr-only' : styles.legend}>{legend}</legend>
        {model.choices.map((choice) => (
          <label key={choice.id} className={styles.option}>
            <input
              type="radio"
              name={name}
              value={choice.id}
              checked={model.selected === choice.id}
              onChange={() => {
                model.select(choice.id);
              }}
            />
            <span className={styles.radio} aria-hidden="true" />
            <span className={styles.name}>
              {choice.title}
              {choice.badge !== undefined && <OfferBadge kind={choice.badge} offer={choice.offer} />}
            </span>
            <span className={styles.price}>
              {choice.reference !== undefined && (
                <span className={styles.reference}>
                  <s aria-hidden="true">{choice.reference}</s>
                  <span className="sr-only">{t('pick.usualPrice', { amount: choice.reference })} </span>
                </span>
              )}
              {choice.billed}
            </span>
            <span className={styles.unit}>{choice.unit}</span>
            <span className={styles.note}>
              <Rich text={choice.note} />
            </span>
            {choice.id === 'pro_yearly' && anchors?.perDay !== undefined && (
              <span className={styles.perDay}>{anchors.perDay}</span>
            )}
            {choice.offer?.personalised === true && (
              <span className={styles.note}>{t('pick.personalised')}</span>
            )}
            {choice.offer !== undefined && countdown !== undefined && (
              <span className={styles.deadline}>
                <OfferCountdown
                  {...countdown}
                  closesAt={choice.offer.closesAt}
                  green={isNight(choice.offer.creative)}
                />
              </span>
            )}
          </label>
        ))}
      </fieldset>
      {anchors?.compare !== undefined && (
        <p className={styles.anchor}>
          <span className={styles.anchorIcon} aria-hidden="true">
            <Icon name="check" size={14} weight={2.4} />
          </span>
          <span>
            {anchors.months !== undefined && <b>{anchors.months} </b>}
            {anchors.compare}
          </span>
        </p>
      )}
    </>
  );
}

export function BuyButton({
  model,
  trial,
  busy,
  disabled,
  describedBy,
  onBuy,
}: {
  model: KeepProModel;
  trial: boolean;
  busy: boolean;
  disabled: boolean;
  describedBy: string;
  onBuy: (choice: PlanChoice) => void;
}): React.JSX.Element {
  const choice = model.choice;
  const label =
    choice === undefined
      ? model.waiting === 'unavailable'
        ? t('buy.unavailable')
        : t('buy.loading')
      : busy
        ? t('buy.opening')
        : buyLabel(choice, trial);
  return (
    <button
      type="button"
      className={styles.buy}
      disabled={disabled || choice === undefined}
      aria-busy={busy ? true : undefined}
      aria-describedby={describedBy}
      onClick={() => {
        if (choice !== undefined) onBuy(choice);
      }}
    >
      {label}
    </button>
  );
}

/** The trust row and the legal sentence for the chosen plan, under the button. */
export function BuyFoot({
  model,
  trial,
  ids,
}: {
  model: KeepProModel;
  trial: boolean;
  ids: { trust: string; legal: string };
}): React.JSX.Element | null {
  const state = useBilling((s) => s.state);
  if (model.choice === undefined) return null;
  // During the trial, what happens to its remaining days: added to the
  // first year where the seller allows it (the server says, `trialDaysBack`),
  // else said plainly that they end when the plan starts.
  const running = trial ? runningTrial(state, new Date(serverNow())) : undefined;
  const left = running === undefined ? undefined : trialDaysLeft(running.endsAt, new Date(serverNow()));
  // Days the server will add, said with their number and set apart, since
  // they are worth something (sales plan B: say it plainly).
  const added = trialDaysBackAdded(state, model.choice.offer, serverNow());
  const back = left !== undefined && model.choice.offer?.trialDaysBack === true;
  const days =
    left === undefined || back
      ? undefined
      : left === 0
        ? t('pick.daysEndToday')
        : t('pick.daysEnd', { count: left });
  return (
    <>
      <p className={styles.trust} id={ids.trust}>
        {trustLine(trial, model.store)}
      </p>
      {/* The 14-day refund is the web's own promise (lexpad.app/refunds);
          Google Play and Apple refund under their own rules, so it is
          said only where Paddle sells. */}
      {model.store === 'paddle' && (
        <p className={cx(styles.trust, styles.moneyBack)}>
          <Icon name="check" size={14} weight={2.4} />
          {t('trust.moneyBack')}
        </p>
      )}
      {back && (
        <p className={styles.daysBack}>
          <Icon name="gift" size={16} />
          <span>{added > 0 ? t('pick.daysBackCount', { count: added }) : t('pick.daysBack')}</span>
        </p>
      )}
      {days !== undefined && <p className={styles.trust}>{days}</p>}
      <p className={styles.disclosure} id={ids.legal}>
        {disclosure(model.choice, model.store)}
      </p>
    </>
  );
}

/**
 * Terms, Privacy, and (on the web) Refunds; in the iPhone app the Restore
 * purchases button. On the web, the seller-of-record line first.
 */
export function LegalRow({
  store,
  restore,
  disabled = false,
}: {
  store: Store;
  restore?: AppStoreRestore | undefined;
  disabled?: boolean;
}): React.JSX.Element {
  const said =
    restore === undefined || restore.status === 'restoring' ? undefined : restoreWords(restore.status);
  return (
    <>
      <p className={styles.legal}>
        {store === 'paddle' && <>{t('legal.paddle')} </>}
        <a href={ABOUT_LINKS.terms} target="_blank" rel="noopener noreferrer">
          {t('upgrade.termsOfUse')}
        </a>
        <span aria-hidden="true"> · </span>
        <a href={ABOUT_LINKS.privacy} target="_blank" rel="noopener noreferrer">
          {t('upgrade.privacyPolicy')}
        </a>
        {store === 'paddle' && (
          <>
            <span aria-hidden="true"> · </span>
            <a href={ABOUT_LINKS.refunds} target="_blank" rel="noopener noreferrer">
              {t('legal.refunds')}
            </a>
          </>
        )}
        {store === 'apple' && restore !== undefined && (
          <>
            <span aria-hidden="true"> · </span>
            <button
              type="button"
              className={styles.legalButton}
              disabled={disabled || restore.status === 'restoring'}
              onClick={restore.run}
            >
              {restore.status === 'restoring' ? t('upgrade.restoring') : t('upgrade.restore')}
            </button>
          </>
        )}
      </p>
      {said !== undefined && (
        <p className={styles.legal} role="status">
          {said}
        </p>
      )}
    </>
  );
}

/** What happens when, for the chosen plan: today, and when it renews. */
export function HowItWorks({
  choice,
  trial,
  now,
}: {
  choice: PlanChoice;
  trial: boolean;
  now: Date;
}): React.JSX.Element {
  const state = useBilling((s) => s.state);
  const yearly = choice.id === 'pro_yearly';
  // The first paid period starts today (buying ends the trial at once),
  // and where the offer says so the trial's remaining whole days are added
  // to it, as the server will (`trialDaysBackAdded`); a bonus offer's days
  // move the first renewal later too.
  const renews = new Date(now.getTime());
  if (yearly) renews.setFullYear(renews.getFullYear() + choice.periods);
  else renews.setMonth(renews.getMonth() + choice.periods);
  renews.setDate(
    renews.getDate() + trialDaysBackAdded(state, choice.offer, now.getTime()) + bonusDays(choice.offer),
  );
  const renewsDate = renews.toLocaleDateString(undefined, {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  });
  return (
    <section className={styles.how} aria-labelledby="how-it-works">
      <h2 id="how-it-works" className={styles.sectionTitle}>
        {t('howBuy.title')}
      </h2>
      <ol className={styles.timeline}>
        <li>
          <span className={cx(styles.dot, styles.dotNow)} aria-hidden="true">
            <Icon name="check" size={16} weight={2.2} />
          </span>
          <span className={styles.when}>{t('howBuy.today')}</span>
          <p className={styles.what}>
            {t(trial ? 'howBuy.payKeep' : 'howBuy.payGet', { amount: choice.billed })}
          </p>
        </li>
        <li>
          <span className={styles.dot} aria-hidden="true">
            <Icon name="clock" size={15} />
          </span>
          <span className={styles.when}>{yearly ? renewsDate : t('howBuy.everyMonth')}</span>
          <p className={styles.what}>
            {yearly
              ? t('howBuy.renewsYear', { amount: choice.renewal })
              : t('howBuy.renewsMonth', { amount: choice.renewal })}
          </p>
        </li>
      </ol>
    </section>
  );
}

/**
 * "This price has ended", with the prices of today when the server sent
 * them (§10.1): said the moment the end passes on screen, before the plan
 * is read again.
 */
export function EndedLine({ offer }: { offer?: Offer | undefined } = {}): React.JSX.Element {
  const state = useBilling((s) => s.state);
  // A bonus offer never changed the price, so it is the offer that ended.
  const bonus = bonusDays(offer) > 0;
  const prices = paidPrices(state);
  const yearly = prices.find((p) => p.id === 'pro_yearly');
  const monthly = prices.find((p) => p.id === 'pro_monthly');
  return (
    <p className={styles.trust} role="status">
      {yearly !== undefined && monthly !== undefined
        ? t(bonus ? 'moment.endedBonus' : 'moment.ended', {
            yearly: formatPrice(yearly),
            monthly: formatPrice(monthly),
          })
        : t(bonus ? 'moment.endedBonusPlain' : 'moment.endedPlain')}
    </p>
  );
}
