import { useRef, useState } from 'react';
import { t } from '@/i18n/index.js';
import { restoreAppStore } from './appstore.js';
import { useBilling } from './state.js';

/** Where a "Restore purchases" tap has got to. */
export type RestoreStatus = 'idle' | 'restoring' | 'nothing' | 'notYours' | 'failed';

export interface AppStoreRestore {
  status: RestoreStatus;
  run: () => void;
}

/**
 * "Restore purchases" in the iPhone app: asks the App Store again (which may
 * show the Apple Account sheet, so only ever on a tap), sends what this Apple
 * Account holds to the server, and calls `onPro` when the plan comes back as
 * Pro. Closing Apple's sheet is not a failure and says nothing.
 */
export function useAppStoreRestore(onPro: () => void): AppStoreRestore {
  const apply = useBilling((s) => s.apply);
  const [status, setStatus] = useState<RestoreStatus>('idle');
  const running = useRef(false);
  const run = (): void => {
    if (running.current) return;
    running.current = true;
    setStatus('restoring');
    restoreAppStore({ sync: true })
      .then((result) => {
        switch (result.kind) {
          case 'restored':
            apply(result.state);
            // A subscription that has lapsed comes back as Free: there was
            // nothing running to restore.
            if (result.state.plan === 'pro') {
              setStatus('idle');
              onPro();
            } else {
              setStatus('nothing');
            }
            return;
          case 'cancelled':
            setStatus('idle');
            return;
          default:
            setStatus(result.kind);
        }
      })
      .catch(() => {
        setStatus('failed');
      })
      .finally(() => {
        running.current = false;
      });
  };
  return { status, run };
}

/** What a restore says once it has an answer, or nothing while idle. */
export function restoreWords(status: RestoreStatus): string | undefined {
  switch (status) {
    case 'restoring':
      return t('upgrade.restoring');
    case 'nothing':
      return t('upgrade.restoreNothing');
    case 'notYours':
      return t('upgrade.appleNotYours');
    case 'failed':
      return t('error.generic');
    default:
      return undefined;
  }
}
