/**
 * A catalogue string with <b>…</b> around the part that carries the money
 * ("Then <b>$29.99 a year</b> from your second year."), drawn as text and
 * <b>; nothing else is read as markup, so a value can never inject any.
 */
export function Rich({ text }: { text: string }): React.JSX.Element {
  const parts = text.split(/(<b>.*?<\/b>)/);
  return (
    <>
      {parts.map((part, index) =>
        part.startsWith('<b>') && part.endsWith('</b>') ? (
          <b key={index}>{part.slice(3, -4)}</b>
        ) : (
          <span key={index}>{part}</span>
        ),
      )}
    </>
  );
}
