import { useEffect, useState } from 'react';
import type { Offer } from './offer.js';
import { onAndroid, onIOS } from './play.js';
import { planChoices, type PaidPlanId, type PlanChoice, type Store } from './planChoices.js';
import { useBilling } from './state.js';
import { useOfferWords } from './useOfferWords.js';

/**
 * How long a selling screen waits for the seller's prices before it says
 * they are not available (offer presentation spec §8.4: 10 seconds).
 */
export const PRICE_PATIENCE_MS = 10_000;

/** The store that takes the payment on this client. */
export function storeHere(): Store {
  if (onIOS()) return 'apple';
  return onAndroid() ? 'google_play' : 'paddle';
}

export interface KeepProModel {
  choices: PlanChoice[];
  selected: PaidPlanId;
  select: (id: PaidPlanId) => void;
  choice: PlanChoice | undefined;
  store: Store;
  /** No price yet: "Loading price…", then after the patience "Prices are not available right now". */
  waiting: 'loading' | 'unavailable' | undefined;
}

export function useKeepPro(offer: Offer | undefined): KeepProModel {
  const state = useBilling((s) => s.state);
  const words = useOfferWords(offer);
  const choices = planChoices(state, offer, words);
  const [selected, select] = useState<PaidPlanId>('pro_yearly');
  const choice = choices.find((one) => one.id === selected) ?? choices[0];
  const [late, setLate] = useState(false);
  const empty = choices.length === 0;
  useEffect(() => {
    if (!empty) return;
    const timer = window.setTimeout(() => {
      setLate(true);
    }, PRICE_PATIENCE_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, [empty]);
  return {
    choices,
    selected: choice?.id ?? selected,
    select,
    choice,
    store: storeHere(),
    waiting: empty ? (late ? 'unavailable' : 'loading') : undefined,
  };
}
