/**
 * What an offer's countdown says, stage by stage (offer presentation spec
 * 2026-10-13 §4.1; uiux offers spec §3.1). Pure: the component passes the
 * deadline, the server's time and where it is drawn.
 *
 * | Time left            | Opened (Plan page, sheet, full screen)      | Feed (Today banner, end card) |
 * |----------------------|---------------------------------------------|-------------------------------|
 * | more than 7 days     | "Early price open until Sat, Oct 24"        | same                          |
 * | 7 days to 48 h       | "5 days left · until Sun, Oct 18" + pips    | "5 days left"                 |
 * | 48 h to 24 h         | "Early price ends tomorrow at 8:38 PM"      | same                          |
 * | last live hours      | "Ends in 05:12:00" + "today at 7:50 PM"     | "Early price ends today at…"  |
 * | the rest of the day  | "Early price ends today at 7:50 PM"         | same                          |
 * | after                | "This price has ended"                      | (removed)                     |
 *
 * Live seconds come only from the operator's `liveSecondsFromHours`
 * (never more than 24) and only on surfaces the learner opened, never with
 * reduced motion, Celebrations off or the pause pressed. `dateOnly` keeps
 * it calm: always the date. Every text counts to the account's own
 * `closesAt`; there is no countdown without one.
 */
import { getLocale, t } from '@/i18n/index.js';
import { calendarDay, lastDayOf } from './offer.js';

const SECOND = 1000;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/** Days left from which the "N days left" stage and its pips begin (§4.1). */
export const COUNTDOWN_DAYS_FROM = 7;
/** Hours left from which the deadline is said with its time (§4.1). */
export const COUNTDOWN_TIME_FROM_HOURS = 48;
/** The most hours of live seconds the operator may ask for (§4.1). */
export const LIVE_SECONDS_MAX_HOURS = 24;
/** The day pips' count: one per day of the last week (uiux §3.1). */
export const COUNTDOWN_PIPS = 7;

/** Where a countdown is drawn. Opened surfaces may tick seconds; the feed never does. */
export type CountdownSurface = 'opened' | 'feed';

export type CountdownStage = 'date' | 'days' | 'tomorrow' | 'today' | 'live' | 'ended';

/** The stage names the offer's funnel uses (`countdownStage`). */
export type CountdownEventStage = 'date' | 'days' | 'tomorrow' | 'live' | 'ended';

/**
 * How a countdown speaks: `auto` (the stages above), `dateOnly` (always the
 * date), or `moment`, the moment offer's own table (2026-10-16 study
 * §10.1): the fixed end always shown, "N days left" beside it, then
 * "tomorrow at", and live seconds only in the last 24 hours on opened
 * surfaces.
 */
export type CountdownStyle = 'auto' | 'dateOnly' | 'moment';

export interface CountdownInput {
  closesAt: Date;
  /** The server's time, in milliseconds. */
  now: number;
  surface: CountdownSurface;
  /** The operator's live-seconds window, 0 (never) to 24 hours. */
  liveSecondsFromHours: number;
  style: CountdownStyle;
  /** Reduced motion, Celebrations off, or the pause pressed: minute steps only. */
  calm: boolean;
  /** "Early price": what the countdown is about. Absent reads plainly. */
  label?: string | undefined;
  zone?: string | undefined;
  /**
   * The device's zone as a reader names it ("Berlin"), only when it is not
   * the account's own: then every time said carries it (§10.1).
   */
  zoneName?: string | undefined;
}

export interface CountdownView {
  stage: CountdownStage;
  /** Everything but the live digits: "Early price ends today at 7:50 PM", or "Ends in". */
  text: string;
  /** "05:12:00" in the live stage, in the UI locale's digits. */
  digits?: string;
  /** Under the live digits: "today at 7:50 PM". */
  under?: string;
  /** Days still open, for the pips (days stage on opened surfaces). */
  pipsOpen?: number;
  /** A small line beside the end: "3 days left" (the moment offer's first stage). */
  small?: string;
  /** One static sentence for a screen reader, changed only with the stage. */
  sr: string;
  /** In the last 48 hours: gold ink. */
  soon: boolean;
  /** How often the text can change. */
  every: 'second' | 'minute';
}

/** The event stage for the funnel. */
export function eventStage(stage: CountdownStage): CountdownEventStage {
  return stage === 'today' ? 'live' : stage;
}

function clock(at: Date, zone: string | undefined): string {
  return at.toLocaleTimeString(undefined, { timeZone: zone, hour: 'numeric', minute: '2-digit' });
}

/** When the deadline falls, said from today: "today at 7:50 PM", "tonight at midnight", "Mon at 9:00 AM". */
export function whenWords(closesAt: Date, now: number, zone?: string): string {
  const today = calendarDay(new Date(now), zone);
  const day = calendarDay(closesAt, zone);
  const lastMoment = new Date(closesAt.getTime() - 1);
  const atMidnight = calendarDay(lastMoment, zone) !== day;
  if (atMidnight) {
    const before = calendarDay(lastMoment, zone);
    if (before === today) return t('countdown.tonightMidnight');
    if (before === today + 1) return t('countdown.tomorrowMidnight');
  }
  const time = clock(closesAt, zone);
  if (day === today) return t('countdown.todayAt', { time });
  if (day === today + 1) return t('countdown.tomorrowAt', { time });
  const weekday = closesAt.toLocaleDateString(undefined, { timeZone: zone, weekday: 'short' });
  return t('countdown.dayAt', { day: weekday, time });
}

/** hh:mm:ss in the UI locale's digits, two-digit hours always. */
export function liveDigits(leftMs: number): string {
  // Rounded up: a countdown reads 00:00:01 in its last second, never 00:00:00 before the end.
  const total = Math.max(0, Math.ceil(leftMs / SECOND));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const seconds = total % 60;
  const two = new Intl.NumberFormat(getLocale(), { minimumIntegerDigits: 2, useGrouping: false });
  return `${two.format(hours)}:${two.format(minutes)}:${two.format(seconds)}`;
}

/** What the countdown says at `now`, or undefined when the deadline cannot be read. */
export function countdownView(input: CountdownInput): CountdownView | undefined {
  const closes = input.closesAt.getTime();
  if (Number.isNaN(closes)) return undefined;
  if (input.style === 'moment') return momentView(input);
  const left = closes - input.now;
  const labelled = input.label !== undefined && input.label !== '';
  if (left <= 0) {
    const text = t('countdown.ended');
    return { stage: 'ended', text, sr: text, soon: true, every: 'minute' };
  }
  const now = new Date(input.now);
  const date = lastDayOf(input.closesAt, now, input.zone);
  const label = input.label ?? '';

  if (input.style === 'dateOnly' || left > COUNTDOWN_DAYS_FROM * DAY) {
    const text = labelled
      ? t('countdown.openUntil', { label, date })
      : t('countdown.openUntilPlain', { date });
    return { stage: 'date', text, sr: `${text}.`, soon: false, every: 'minute' };
  }
  if (left > COUNTDOWN_TIME_FROM_HOURS * HOUR) {
    const days = Math.ceil(left / DAY);
    const opened = input.surface === 'opened';
    const text = opened
      ? t('countdown.daysUntil', { count: days, date })
      : t('countdown.days', { count: days });
    return {
      stage: 'days',
      text,
      sr: `${t('countdown.daysUntil', { count: days, date })}.`,
      soon: false,
      every: 'minute',
      ...(opened ? { pipsOpen: Math.min(COUNTDOWN_PIPS, days) } : {}),
    };
  }
  const when = whenWords(input.closesAt, input.now, input.zone);
  const ends = labelled ? t('countdown.labelEnds', { label, when }) : t('countdown.ends', { when });
  const liveHours = Math.min(LIVE_SECONDS_MAX_HOURS, Math.max(0, input.liveSecondsFromHours));
  if (left > 24 * HOUR) {
    return { stage: 'tomorrow', text: ends, sr: `${ends}.`, soon: true, every: 'minute' };
  }
  if (input.surface === 'opened' && !input.calm && liveHours > 0 && left <= liveHours * HOUR) {
    return {
      stage: 'live',
      text: t('countdown.endsIn'),
      digits: liveDigits(left),
      under: when,
      sr: `${ends}.`,
      soon: true,
      every: 'second',
    };
  }
  return { stage: 'today', text: ends, sr: `${ends}.`, soon: true, every: 'minute' };
}

/** Hours left from which the moment offer says "tomorrow at" rather than its date (§10.1). */
export const MOMENT_TOMORROW_FROM_HOURS = 48;
/** Hours left in which the Today banner counts minutes rather than saying the time (§10.1). */
export const MOMENT_MINUTES_FROM_HOURS = 1;

function withZone(when: string, zoneName: string | undefined): string {
  return zoneName === undefined || zoneName === ''
    ? when
    : t('countdown.moment.zone', { when, zone: zoneName });
}

/** "Sat, Oct 24, 18:00": the fixed end, always said (§10.1). */
export function momentEnd(closesAt: Date, zone?: string): string {
  const day = closesAt.toLocaleDateString(undefined, {
    timeZone: zone,
    weekday: 'short',
    day: 'numeric',
    month: 'short',
  });
  return `${day}, ${clock(closesAt, zone)}`;
}

/** "Sat 18:00": the end as the Today banner says it. */
export function momentEndShort(closesAt: Date, zone?: string): string {
  const day = closesAt.toLocaleDateString(undefined, { timeZone: zone, weekday: 'short' });
  return `${day} ${clock(closesAt, zone)}`;
}

/**
 * The moment offer's countdown (2026-10-16 study §10.1). Opened surfaces
 * (the offer sheet, the Plan page) and the Today banner:
 *
 * | Time left  | Opened                                         | Today banner                 |
 * |------------|------------------------------------------------|------------------------------|
 * | 72 h–48 h  | "Yours until Sat, Oct 24, 18:00" + "2 days left" | "Your price · until Sat 18:00" |
 * | 48 h–24 h  | "Ends tomorrow at 18:00" (the date under it)   | "Ends tomorrow at 18:00"     |
 * | last 24 h  | live "Ends in 05:12:33", "today at 18:00" under | "Ends today at 18:00"        |
 * | last hour  | the same                                       | "Ends in 42 min"             |
 * | 0          | "This price has ended"                         | (removed)                    |
 *
 * Reduced motion, Celebrations off or the pause: minute steps ("Ends in
 * 5 h 12 min"). The end is always said beside any count.
 */
function momentView(input: CountdownInput): CountdownView {
  const closes = input.closesAt;
  const left = closes.getTime() - input.now;
  if (left <= 0) {
    const text = t('countdown.ended');
    return { stage: 'ended', text, sr: text, soon: true, every: 'minute' };
  }
  const opened = input.surface === 'opened';
  const zoneName = input.zoneName;
  const full = withZone(momentEnd(closes, input.zone), zoneName);
  if (left > MOMENT_TOMORROW_FROM_HOURS * HOUR) {
    const days = Math.floor(left / DAY);
    const text = opened
      ? t('countdown.moment.yoursUntil', { date: full })
      : t('countdown.moment.feedUntil', { date: withZone(momentEndShort(closes, input.zone), zoneName) });
    const small = t('countdown.moment.daysLeft', { count: days });
    return {
      stage: 'days',
      text,
      sr: `${t('countdown.moment.yoursUntil', { date: full })}.`,
      soon: false,
      every: 'minute',
      ...(opened ? { small } : {}),
    };
  }
  const when = withZone(whenWords(closes, input.now, input.zone), zoneName);
  const ends = t('countdown.moment.ends', { when });
  if (left > 24 * HOUR) {
    return {
      stage: 'tomorrow',
      text: ends,
      sr: `${ends}.`,
      soon: true,
      every: 'minute',
      ...(opened ? { under: full } : {}),
    };
  }
  const liveHours = Math.min(LIVE_SECONDS_MAX_HOURS, Math.max(0, input.liveSecondsFromHours));
  if (opened) {
    if (!input.calm && liveHours > 0 && left <= liveHours * HOUR) {
      return {
        stage: 'live',
        text: t('countdown.endsIn'),
        digits: liveDigits(left),
        under: when,
        sr: `${ends}.`,
        soon: true,
        every: 'second',
      };
    }
    // Minute steps, rounded up: never says less time than is left.
    const minutesLeft = Math.ceil(left / MINUTE);
    const text =
      minutesLeft >= 60
        ? t('countdown.moment.endsInHours', {
            hours: Math.floor(minutesLeft / 60),
            minutes: minutesLeft % 60,
          })
        : t('countdown.moment.endsInMinutes', { minutes: minutesLeft });
    return { stage: 'today', text, under: when, sr: `${ends}.`, soon: true, every: 'minute' };
  }
  if (left <= MOMENT_MINUTES_FROM_HOURS * HOUR) {
    const text = t('countdown.moment.endsInMinutes', { minutes: Math.ceil(left / MINUTE) });
    return { stage: 'today', text, sr: `${ends}.`, soon: true, every: 'minute' };
  }
  return { stage: 'today', text: ends, sr: `${ends}.`, soon: true, every: 'minute' };
}
