/**
 * The night look (uiux spec 2026-10-24, Black Friday plan F1): a campaign
 * whose look names the `night` gradient draws its surfaces on the deep-ink
 * card, the same in both themes, mint its only colour. Its colours may come
 * from the campaign (`look.night`); a set that fails the contrast check is
 * replaced by the built-in night colours (tokens.css `--night-*`), never by
 * the house look, so a typo cannot turn the sale into a green card.
 */
import type { CSSProperties } from 'react';
import type { ApiResolvedCreative } from '@/api/types.js';
import { getLocale, t } from '@/i18n/index.js';
import { lastDayOf, OFFER_LAST_HOURS } from './offer.js';

type Creative = ApiResolvedCreative | undefined;
type Gradient = ApiResolvedCreative['look']['gradient'];

/** The presets this build can draw; anything else draws the house look (F4). */
const GRADIENTS: readonly string[] = ['house', 'dawn', 'spring', 'winter', 'dusk', 'night'];

/** The gradient a creative's look names, or the house one when this build does not know it. */
export function knownGradient(creative: Creative): Gradient {
  const named = creative?.look.gradient as string | undefined;
  return named !== undefined && GRADIENTS.includes(named) ? (named as Gradient) : 'house';
}

export function isNight(creative: Creative): boolean {
  return knownGradient(creative) === 'night';
}

const HEX = /^#[0-9a-f]{6}$/i;

function channel(hex: string, at: number): number {
  const c = Number.parseInt(hex.slice(at, at + 2), 16) / 255;
  return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
}

/** WCAG 2 relative luminance of a #rrggbb colour. */
export function luminance(hex: string): number {
  return 0.2126 * channel(hex, 1) + 0.7152 * channel(hex, 3) + 0.0722 * channel(hex, 5);
}

/** WCAG 2 contrast ratio of two #rrggbb colours. */
export function contrast(a: string, b: string): number {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x) as [number, number];
  return (hi + 0.05) / (lo + 0.05);
}

/** Text and accent on the ground, button text on the accent (spec §8; the server checks the same). */
const MIN_CONTRAST = 4.5;
/**
 * The ground must stay a dark card on a light page: OKLCH lightness below
 * 0.25 in the spec, about 0.25³ in relative luminance. The server's
 * `maxNightGroundLuminance` is the same number.
 */
const MAX_GROUND_LUMINANCE = 0.0156;
/** The pill's outline is the accent at 55% (tokens.css `--night-accent-line`), as a hex alpha. */
const ACCENT_LINE_ALPHA = '8c';

/** The campaign's own night colours as CSS variables, or undefined for the built-in ones. */
export function nightStyle(creative: Creative): CSSProperties | undefined {
  const n = creative?.look.night;
  if (n === undefined || !isNight(creative)) return undefined;
  const all = [n.bg, n.fg, n.dim, n.accent, n.accentFg];
  if (!all.every((c) => HEX.test(c))) return undefined;
  const readable =
    contrast(n.fg, n.bg) >= MIN_CONTRAST &&
    contrast(n.dim, n.bg) >= MIN_CONTRAST &&
    contrast(n.accent, n.bg) >= MIN_CONTRAST &&
    contrast(n.accentFg, n.accent) >= MIN_CONTRAST &&
    luminance(n.bg) <= MAX_GROUND_LUMINANCE;
  if (!readable) return undefined;
  return {
    '--night-bg': n.bg,
    '--night-fg': n.fg,
    '--night-dim': n.dim,
    '--night-accent': n.accent,
    '--night-accent-line': `${n.accent}${ACCENT_LINE_ALPHA}`,
    '--night-accent-fg': n.accentFg,
    '--night-btn': n.accent,
  } as CSSProperties;
}

const HOUR = 3_600_000;
const MINUTE = 60_000;

/**
 * The time an end is said at. An offer that closes "at 23:59 local" is sent
 * as that minute; one sent as the midnight after it is said as 23:59 of the
 * day it ends, never as "00:00" of the next.
 */
export function closingTime(end: Date): string {
  const shown = end.getHours() === 0 && end.getMinutes() === 0 ? new Date(end.getTime() - MINUTE) : end;
  return shown.toLocaleTimeString(getLocale(), { hour: 'numeric', minute: '2-digit' });
}

/** The day an end is said on: the day of its last minute. */
export function closingDate(end: Date, now: Date): string {
  return lastDayOf(
    new Date(end.getTime() + (end.getHours() === 0 && end.getMinutes() === 0 ? 0 : MINUTE)),
    now,
  );
}

/**
 * The closing line of a night card: "Until Wed, Dec 2, 11:59 PM your time",
 * then "Ends today at 11:59 PM, your time" in the last day; undefined once
 * it has closed (the card goes then).
 */
export function closingWords(closesAt: string | undefined, now: Date): string | undefined {
  if (closesAt === undefined) return undefined;
  const end = new Date(closesAt);
  const left = end.getTime() - now.getTime();
  if (Number.isNaN(left) || left <= 0) return undefined;
  if (left <= OFFER_LAST_HOURS * HOUR) return t('night.endsToday', { time: closingTime(end) });
  return t('night.until', { date: closingDate(end, now), time: closingTime(end) });
}

/**
 * A sentence with one amount in it, split so the amount can sit in its own
 * `<bdi dir="ltr">`: an English price inside a right-to-left sentence
 * otherwise reads in the wrong order (spec §5.4).
 */
export function aroundAmount(sentence: (amount: string) => string): [string, string] {
  const marker = '\u0000';
  const [before = '', after = ''] = sentence(marker).split(marker);
  return [before, after];
}
