import { useEffect, useState } from 'react';
import { config } from '@/api/endpoints.js';
import { useBilling } from '@/features/billing/state.js';
import { invitesInThisApp } from './where.js';

/** What the "Pay or invite" line promises, all from the server's referral flag. */
export interface InviteReward {
  /** Days of Pro each side gets for one friend who starts learning. */
  days: number;
  /** How many friends the line names, when the flag names any. */
  friends?: number | undefined;
}

/**
 * The invitation's reward for the "Pay or invite" line (sales plan 6-و):
 * read from `/config` (`referralDays`, `referralPitchFriends`), never
 * written here. Undefined while the programme is off, where invitations
 * are not offered (`where.ts`: not in the iPhone app; the web, the desktop
 * and the Android app do), and for somebody who pays (they are thanked,
 * not sold to) unless `payers` asks for them too (Settings → Plan's own
 * link: a payer's days move their next payment).
 */
export function useInviteReward({ payers = false }: { payers?: boolean } = {}): InviteReward | undefined {
  const paying = useBilling(
    (s) => s.state?.plan === 'pro' && s.state.provider !== undefined && s.state.provider !== 'manual',
  );
  const offered = invitesInThisApp() && (payers || !paying);
  const [reward, setReward] = useState<InviteReward | undefined>(undefined);
  useEffect(() => {
    if (!offered) return;
    let live = true;
    config
      .get()
      .then((answer) => {
        if (!live) return;
        const days = answer.referralDays;
        setReward(days === undefined ? undefined : { days, friends: answer.referralPitchFriends });
      })
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, [offered]);
  return offered ? reward : undefined;
}

/**
 * The days the line names: one friend's days, or the named friends' days
 * together ("Invite 2 friends who start learning: 28 more days of Pro").
 */
export function pitchDays(reward: InviteReward): number {
  return reward.friends === undefined ? reward.days : reward.friends * reward.days;
}
