import { useEffect, useState } from 'react';
import type { ApiResolvedCreative, ApiResolvedImage } from '@/api/types.js';
import { knownGradient } from '../night.js';
import { cx } from '@/lib/cx.js';
import { resolveTheme, useTheme } from '@/lib/theme.js';
import { HouseArt } from './Seal.js';
import { focalPosition, mirrored, pickImage, sourceSets, type ImageRole } from './pickImage.js';
import styles from './CampaignArt.module.css';

/** How long a picture may take before the house art is all there is (offer presentation §8.4). */
export const ART_PATIENCE_MS = 2500;

type Gradient = ApiResolvedCreative['look']['gradient'];

function useDirection(): 'ltr' | 'rtl' {
  return typeof document !== 'undefined' && document.documentElement.dir === 'rtl' ? 'rtl' : 'ltr';
}

/** The theme in view: the app's own setting, `system` resolved against the device. */
function useResolvedTheme(): 'light' | 'dark' {
  const theme = useTheme((s) => s.theme);
  return resolveTheme(theme);
}

/**
 * One campaign picture as `<picture>`: AVIF, WebP, then JPEG or PNG, each
 * with its widths, `width`/`height` always set, decoded off the main
 * thread, lazy unless it is the full-screen offer's band. It reports when
 * it loaded or failed; a failure hides it and leaves what is under it.
 */
export function CampaignImage({
  image,
  sizes,
  priority = false,
  onState,
}: {
  image: ApiResolvedImage;
  sizes: string;
  priority?: boolean;
  onState?: (ok: boolean) => void;
}): React.JSX.Element | null {
  const direction = useDirection();
  const [failed, setFailed] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const flip = mirrored(image, direction);
  const sets = sourceSets(image);
  if (failed || sets.fallback === undefined) return null;
  return (
    <picture className={cx(styles.picture, loaded && styles.loaded)}>
      {sets.sources.map((source) => (
        <source key={source.type} type={source.type} srcSet={source.srcSet} sizes={sizes} />
      ))}
      <img
        className={cx(styles.image, flip && styles.flip)}
        src={sets.fallback.src}
        srcSet={sets.fallback.srcSet}
        sizes={sizes}
        width={image.width}
        height={image.height}
        alt={image.alt ?? ''}
        decoding="async"
        loading={priority ? 'eager' : 'lazy'}
        {...(priority ? { fetchPriority: 'high' as const } : {})}
        style={{ objectPosition: focalPosition(image, flip) }}
        onLoad={() => {
          setLoaded(true);
          onState?.(true);
        }}
        onError={() => {
          setFailed(true);
          onState?.(false);
        }}
      />
    </picture>
  );
}

/**
 * A campaign's art in a box that never changes size (uiux offers spec
 * §5): the gradient preset and the house illustration underneath, from
 * the first frame and with no network, and the campaign's picture over
 * them once it has decoded. Slow, failed or offline, the house art is
 * simply what shows; nothing waits for a picture.
 */
export function CampaignArt({
  role,
  creative,
  sizes,
  priority = false,
  className,
  house,
  onImage,
}: {
  role: ImageRole;
  creative: ApiResolvedCreative | undefined;
  sizes: string;
  priority?: boolean;
  className?: string | undefined;
  /** The house art's own composition for this box. */
  house: { width: number; height: number; fx?: number; fy?: number; fit?: string };
  /** Whether the campaign's picture loaded (for the event's `imageOk`); not called without one. */
  onImage?: (ok: boolean) => void;
}): React.JSX.Element {
  const theme = useResolvedTheme();
  const direction = useDirection();
  const image = pickImage(creative?.images, role, theme, direction);
  const [late, setLate] = useState(false);
  const [ok, setOk] = useState<boolean | undefined>(undefined);
  useEffect(() => {
    if (image === undefined) return;
    const timer = window.setTimeout(() => {
      setLate(true);
    }, ART_PATIENCE_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, [image]);
  useEffect(() => {
    if (late && ok === undefined) onImage?.(false);
    // Reported once, when the patience runs out.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [late]);
  // A preset this build does not know draws the house look (F4); the night
  // card has no art band, so its picture ground is the house one too.
  const named = knownGradient(creative);
  const gradient: Gradient = named === 'night' ? 'house' : named;
  return (
    <div className={cx(styles.box, styles[`gradient_${gradient}`], className)}>
      <HouseArt mirror={direction === 'rtl'} ground={false} {...house} />
      {image !== undefined && (!late || ok === true) && (
        <CampaignImage
          image={image}
          sizes={sizes}
          priority={priority}
          onState={(loaded) => {
            setOk(loaded);
            onImage?.(loaded);
          }}
        />
      )}
    </div>
  );
}
