/**
 * Which campaign picture a surface draws (uiux offers spec §5): by role,
 * then the theme and direction in view, preferring an exact match over
 * `any`. Sources become `srcset` lists per format, best format first.
 * Pure, so the choice has tests.
 */
import type { ApiResolvedImage } from '@/api/types.js';

export type ImageRole = ApiResolvedImage['role'];

function rank(value: string, wanted: string): number {
  if (value === wanted) return 2;
  return value === 'any' ? 1 : 0;
}

export function pickImage(
  images: readonly ApiResolvedImage[] | undefined,
  role: ImageRole,
  theme: 'light' | 'dark',
  direction: 'ltr' | 'rtl',
): ApiResolvedImage | undefined {
  let best: { image: ApiResolvedImage; score: number } | undefined;
  for (const image of images ?? []) {
    if (image.role !== role || image.sources.length === 0) continue;
    const themeScore = rank(image.theme, theme);
    // A picture drawn for the other direction is used only when it may be mirrored.
    const directionScore =
      image.direction === direction ? 2 : image.direction === 'any' ? 1 : image.mirrorInRtl === true ? 1 : 0;
    if (themeScore === 0 || directionScore === 0) continue;
    const score = themeScore * 3 + directionScore;
    if (best === undefined || score > best.score) best = { image, score };
  }
  return best?.image;
}

/** Whether the picture is flipped to read right to left (composition only, never writing). */
export function mirrored(image: ApiResolvedImage, direction: 'ltr' | 'rtl'): boolean {
  return direction === 'rtl' && image.direction !== 'rtl' && image.mirrorInRtl === true;
}

/** The focal point as `object-position`, mirrored with the picture. */
export function focalPosition(image: ApiResolvedImage, flip: boolean): string {
  const x = image.focalX ?? 50;
  const y = image.focalY ?? 50;
  return `${String(flip ? 100 - x : x)}% ${String(y)}%`;
}

type Format = 'avif' | 'webp' | 'jpeg' | 'png';
const TYPES = { avif: 'image/avif', webp: 'image/webp', jpeg: 'image/jpeg', png: 'image/png' } as const;

/** The `<source>` lists, best format first, and the plain fallback `<img>` list. */
export function sourceSets(image: ApiResolvedImage): {
  sources: { type: string; srcSet: string }[];
  fallback: { src: string; srcSet: string } | undefined;
} {
  const by = (format: Format): string =>
    image.sources
      .filter((one) => one.format === format)
      .sort((a, b) => a.width - b.width)
      .map((one) => `${one.url} ${String(one.width)}w`)
      .join(', ');
  const sources = (['avif', 'webp'] as const)
    .map((format) => ({ type: TYPES[format], srcSet: by(format) }))
    .filter((one) => one.srcSet !== '');
  const plain = image.sources
    .filter((one) => one.format === 'jpeg' || one.format === 'png')
    .sort((a, b) => a.width - b.width);
  const any = plain.length > 0 ? plain : [...image.sources].sort((a, b) => a.width - b.width);
  const first = any[0];
  return {
    sources: plain.length > 0 ? sources : [],
    fallback:
      first === undefined
        ? undefined
        : { src: first.url, srcSet: any.map((one) => `${one.url} ${String(one.width)}w`).join(', ') },
  };
}
